TEMPLATES_FILES = {'node_basic': {'index.js': 'const http = require("http");\nconst PORT = process.env.PORT || 8080;\nconst server = http.createServer((req, res) => {\n  res.writeHead(200, { "Content-Type": "text/plain" });\n  res.end("FLIX HOST - Node Basic is running\\n");\n});\nserver.listen(PORT, "0.0.0.0", () => console.log("Listening on port", PORT));\n', 'package.json': '{\n  "name": "flix-node-basic",\n  "version": "1.0.0",\n  "main": "index.js"\n}\n'}, 'node_express': {'index.js': 'const express = require("express");\nconst app = express();\nconst PORT = process.env.PORT || 8080;\napp.get("/", (req, res) => res.json({ status: "ok", message: "FLIX HOST Express template" }));\napp.get("/health", (req, res) => res.json({ status: "healthy" }));\napp.listen(PORT, "0.0.0.0", () => console.log("Listening on port", PORT));\n', 'package.json': '{\n  "name": "flix-express",\n  "version": "1.0.0",\n  "main": "index.js",\n  "dependencies": { "express": "^4.19.2" }\n}\n'}, 'python_basic': {'main.py': 'import os\nfrom http.server import HTTPServer, BaseHTTPRequestHandler\n\nPORT = int(os.environ.get("PORT", 8080))\n\nclass Handler(BaseHTTPRequestHandler):\n    def do_GET(self):\n        self.send_response(200)\n        self.send_header("Content-Type", "text/plain; charset=utf-8")\n        self.end_headers()\n        self.wfile.write(b"FLIX HOST - Python Basic is running\\n")\n    def log_message(self, format, *args):\n        print("[%s] %s" % (self.log_date_time_string(), format % args))\n\nif __name__ == "__main__":\n    print("Listening on port", PORT)\n    HTTPServer(("0.0.0.0", PORT), Handler).serve_forever()\n', 'requirements.txt': '# no external deps\n'}, 'python_fastapi': {'main.py': 'import os\nfrom fastapi import FastAPI\nimport uvicorn\n\napp = FastAPI(title="FLIX HOST FastAPI")\n\n@app.get("/")\ndef root():\n    return {"status": "ok", "message": "FLIX HOST FastAPI template"}\n\n@app.get("/health")\ndef health():\n    return {"status": "healthy"}\n\nif __name__ == "__main__":\n    port = int(os.environ.get("PORT", 8080))\n    uvicorn.run(app, host="0.0.0.0", port=port)\n', 'requirements.txt': 'fastapi==0.115.0\nuvicorn==0.30.6\n'}, 'python_flask': {'app.py': 'import os\nfrom flask import Flask, jsonify\n\napp = Flask(__name__)\n\n@app.get("/")\ndef index():\n    return jsonify(status="ok", message="FLIX HOST Flask template", port=os.environ.get("PORT"))\n\n@app.get("/health")\ndef health():\n    return jsonify(status="healthy")\n\nif __name__ == "__main__":\n    port = int(os.environ.get("PORT", 8080))\n    app.run(host="0.0.0.0", port=port)\n', 'requirements.txt': 'flask==3.0.3\n'}, 'python_telegram_bot': {'bot.py': 'import os\nimport logging\nfrom telegram import Update\nfrom telegram.ext import Application, CommandHandler, ContextTypes\n\nlogging.basicConfig(level=logging.INFO)\nTOKEN = os.environ.get("BOT_TOKEN", "")\n\nasync def start(update: Update, context: ContextTypes.DEFAULT_TYPE):\n    await update.message.reply_text("FLIX HOST Telegram bot is running.")\n\nasync def ping(update: Update, context: ContextTypes.DEFAULT_TYPE):\n    await update.message.reply_text("pong")\n\ndef main():\n    if not TOKEN:\n        print("ERROR: set BOT_TOKEN in Environment Variables")\n        raise SystemExit(1)\n    app = Application.builder().token(TOKEN).build()\n    app.add_handler(CommandHandler("start", start))\n    app.add_handler(CommandHandler("ping", ping))\n    print("Bot started")\n    app.run_polling(allowed_updates=Update.ALL_TYPES)\n\nif __name__ == "__main__":\n    main()\n', 'requirements.txt': 'python-telegram-bot==21.6\n'}}
